with unpacked as (select id, log_ts, latency_ms, status_code, context, cast((status_code & 8) != 0 as int) as is_flagged, context['version'] as version, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier, shiftright(status_code, 2) as status_code_high, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec from app_logs where status_code = 413) select id, log_ts, is_flagged, duration_sec, min(latency_ms) over (partition by tier) as tier_min_latency_ms, round(latency_ms / sum(latency_ms) over (partition by tier), 4) as latency_ms_share, row_number() over (order by log_ts desc, id) as seq_no, lead(latency_ms, 2, 0) over (partition by tier order by duration_sec, id) as next_latency_ms, row_number() over (partition by tier order by duration_sec, id) as row_seq from unpacked where status_code_high > 2;
